    static String out(Object o, ObjectWriterProvider p, String ch) {
        try {
            JSONWriter.Context c = new JSONWriter.Context(p);
            String s = "json".equals(ch) ? JSON.toJSONString(o, c) : JSON.toJSONString(JSONB.parse(JSONB.toBytes(o, c)));
            return s.replaceAll("Q18\\$[A-Z][0-9]+(_[A-Za-z]+)?", "H");
        } catch (Throwable e) {
            return "EXC " + e.getClass().getSimpleName() + ": " + String.valueOf(e.getMessage()).replaceAll("Q18\\$[A-Z][0-9]+(_[A-Za-z]+)?", "H");
        }
    }

    public static void main(String[] args) {
        Map<String, Supplier<Object>> cells = cells();
        for (String ch : new String[]{"json", "jsonb"}) {
            for (Map.Entry<String, Supplier<Object>> e : cells.entrySet()) {
                String asm = out(e.getValue().get(), new ObjectWriterProvider(ObjectWriterCreatorASM.INSTANCE), ch);
                String refl = out(e.getValue().get(), new ObjectWriterProvider(ObjectWriterCreator.INSTANCE), ch);
                System.out.println(ch + " | " + e.getKey() + " || asm " + asm + " || reflect " + refl);
            }
        }
    }
